import itertools

def check_n(n):
    m = n * (n - 1) // 2
    # D1 = 0, D2, D3, ..., Dn
    # Sums are Di + Dj for 1 <= i < j <= n
    # We need these sums to be 1, 2, ..., m
    # D1 = 0, so the sums are D2, D3, ..., Dn, D2+D3, D2+D4, ..., Dn-1+Dn
    # Let D_vals = [D2, D3, ..., Dn]
    # The sums are {D_i for i=1..n-1} + {D_i+D_j for i,j in 1..n-1}
    # No, the sums are {D_i + D_j for 0 <= i < j <= n-1} where D0 = 0
    # So the sums are {D1+D2, D1+D3, ..., D1+Dn, D2+D3, ..., Dn-1+Dn}
    # Since D1 = 0, these are {D2, D3, ..., Dn, D2+D3, ..., Dn-1+Dn}
    for d_vals in itertools.product(range(1, m + 1), repeat=n-1):
        d_list = list(d_vals)
        if not all(d_list[i] < d_list[i+1] for i in range(len(d_list)-1)):
            continue

        sums = set()
        # D_vals are D2, D3, ..., Dn. Let's add D1=0 at the beginning.
        D = [0] + list(d_list)
        for i in range(n):
            for j in range(i + 1, n):
                sums.add(D[i] + D[j])

        if len(sums) == m and max(sums) == m and min(sums) == 1:
            return d_list
    return None

for n in range(3, 8):
    result = check_n(n)
    print(f"n={n}: {result}")

