def check_n_fast(n):
    N = n * (n - 1) // 2
    target_sum = n * (n**2 - n + 2) / 8
    if target_sum != int(target_sum):
        return False
    target_sum = int(target_sum)

    for a1 in range(-N, 1):
        a2 = 1 - a1
        if a2 <= a1: continue

        def backtrack(current_a, current_sums):
            if len(current_a) == n - 1:
                an = N - current_a[-1]
                if an > current_a[-1]:
                    new_sums = set()
                    for i in range(n-1):
                        s = an + current_a[i]
                        if s in current_sums or s < 1 or s > N:
                            return None
                        new_sums.add(s)
                    if len(current_sums | new_sums) == N:
                        return current_a + [an]
                    return None
                return None

            start_ak = current_a[-1] + 1
            end_ak = N - a1

            for ak in range(start_ak, end_ak + 1):
                new_sums = set()
                possible = True
                for i in range(len(current_a)):
                    s = ak + current_a[i]
                    if s in current_sums or s < 1 or s > N:
                        possible = False
                        break
                    new_sums.add(s)

                if possible:
                    res = backtrack(current_a + [ak], current_sums | new_sums)
                    if res: return res
            return None

        res = backtrack([a1, a2], {1})
        if res:
            print(f"n={n} works with {res}")
            return True
    return False

