def find_x_for_n_large(n):
    # For n=6, the sums are 0...14.
    # x_i are in a range of size about 14.
    limit = 15
    for x in itertools.combinations(range(-limit, limit + 1), n):
        x = sorted(list(x))
        sums = set()
        for i in range(n):
            for j in range(i+1, n):
